function knightHops(x: number, y: number): number {
  const tx = Math.abs(x), ty = Math.abs(y);
  const W = tx + 5, H = ty + 5; // coordinates -2 .. t + 2, shifted by 2
  const dist = new Int32Array(W * H).fill(-1);
  const moves = [[1, 2], [2, 1], [-1, 2], [-2, 1], [1, -2], [2, -1], [-1, -2], [-2, -1]];
  const qx: number[] = [0], qy: number[] = [0];
  dist[2 * H + 2] = 0;
  for (let h = 0; h < qx.length; h++) {
    const cx = qx[h], cy = qy[h], d = dist[(cx + 2) * H + cy + 2];
    if (cx === tx && cy === ty) return d;
    for (const [dx, dy] of moves) {
      const nx = cx + dx, ny = cy + dy;
      if (nx < -2 || ny < -2 || nx > tx + 2 || ny > ty + 2) continue;
      const k = (nx + 2) * H + ny + 2;
      if (dist[k] !== -1) continue;
      dist[k] = d + 1;
      qx.push(nx); qy.push(ny);
    }
  }
  return -1;
}

