function knightHops(x: number, y: number): number {
  const memo = new Map<number, number>();
  const go = (a: number, b: number): number => {
    if (a + b === 0) return 0;
    if (a + b === 2) return 2; // (1, 1), (2, 0) and (0, 2) all take two hops
    const key = a * 1000 + b;
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    const res = 1 + Math.min(go(Math.abs(a - 1), Math.abs(b - 2)), go(Math.abs(a - 2), Math.abs(b - 1)));
    memo.set(key, res);
    return res;
  };
  return go(Math.abs(x), Math.abs(y));
}

